import{_ as o,b as a,c as n,e as d,f as e,g as i,h as l,i as c}from"./app-02424545.js";const t={},h=c('<h1 id="前端埋点及监控系统" tabindex="-1"><a class="header-anchor" href="#前端埋点及监控系统" aria-hidden="true">#</a> 前端埋点及监控系统</h1><h2 id="_1-采集数据分类" tabindex="-1"><a class="header-anchor" href="#_1-采集数据分类" aria-hidden="true">#</a> 1. 采集数据分类</h2><ul><li><strong>用户交互数据</strong><br> 如点击、滑动、表单提交等用户行为。</li><li><strong>系统性能数据</strong><br> 页面加载时间、资源加载耗时、首屏渲染时间等。</li><li><strong>系统异常数据</strong><br> JS 错误、接口异常、资源加载失败等。</li></ul><hr><h2 id="_2-埋点方式" tabindex="-1"><a class="header-anchor" href="#_2-埋点方式" aria-hidden="true">#</a> 2. 埋点方式</h2><ul><li><strong>手动埋点（代码埋点）</strong><br> 通过在代码中显式添加埋点逻辑，适合精细化控制，灵活性高，但开发和维护成本较大。</li><li><strong>可视化埋点</strong><br> 借助可视化工具在页面上标记埋点位置，自动生成埋点代码，适合非技术人员参与，降低开发门槛。</li><li><strong>无埋点（全埋点）SDK</strong><br> 通过 SDK 自动监听所有用户行为和事件，无需手动指定埋点，适合快速接入和全量数据采集，但数据量大、后期分析压力较大。</li></ul><hr><h2 id="_3-数据上报方式" tabindex="-1"><a class="header-anchor" href="#_3-数据上报方式" aria-hidden="true">#</a> 3. 数据上报方式</h2><h3 id="_3-1-图片请求-gif-pixel" tabindex="-1"><a class="header-anchor" href="#_3-1-图片请求-gif-pixel" aria-hidden="true">#</a> 3.1 图片请求（GIF/Pixel）</h3><ul><li><strong>防止跨域</strong><br> 图片的 <code>src</code> 属性不会受到跨域限制，常用于数据上报。</li><li><strong>非阻塞</strong><br> 通过 <code>new Image()</code> 方式发送，不影响页面渲染。</li><li><strong>体积小</strong><br> 最小 GIF 文件仅需 43 字节，节省带宽。</li><li><strong>兼容性好</strong><br> 几乎所有浏览器都支持。</li></ul><h3 id="_3-2-接口上报-ajax" tabindex="-1"><a class="header-anchor" href="#_3-2-接口上报-ajax" aria-hidden="true">#</a> 3.2 接口上报（AJAX）</h3><ul><li>通过 <code>XMLHttpRequest</code> 或 <code>fetch</code> 发送数据到后端接口。</li><li>可能会遇到跨域、页面刷新丢失等问题。</li><li>适合需要响应和更复杂数据结构的场景。</li></ul><h3 id="_3-3-web-beacon" tabindex="-1"><a class="header-anchor" href="#_3-3-web-beacon" aria-hidden="true">#</a> 3.3 Web Beacon</h3><ul><li>使用 <code>Navigator.sendBeacon</code> API 实现异步、可靠的数据上报。</li><li><strong>优点</strong><ul><li>不阻塞主线程，浏览器空闲时发送。</li><li>页面卸载（关闭/刷新）时也能保证数据发送。</li></ul></li><li><strong>兼容性</strong><ul><li>现代浏览器支持良好，老旧浏览器可用图片请求兜底。</li></ul></li></ul><hr><h2 id="_4-性能数据采集" tabindex="-1"><a class="header-anchor" href="#_4-性能数据采集" aria-hidden="true">#</a> 4. 性能数据采集</h2><ul><li>可通过 <code>window.performance.timing</code> 或 <code>Performance API</code> 获取页面性能指标，如： <ul><li>DNS 查询耗时</li><li>TCP 连接耗时</li><li>首字节时间（TTFB）</li><li>DOM 渲染完成时间</li><li>页面完全加载时间</li></ul></li><li>也可结合 <code>PerformanceObserver</code> 监听更细粒度的性能数据（如 FCP、LCP、CLS 等）。</li></ul><hr><h2 id="_5-系统错误采集" tabindex="-1"><a class="header-anchor" href="#_5-系统错误采集" aria-hidden="true">#</a> 5. 系统错误采集</h2><h3 id="_5-1-js-错误" tabindex="-1"><a class="header-anchor" href="#_5-1-js-错误" aria-hidden="true">#</a> 5.1 JS 错误</h3><ul><li>通过监听 <code>window.onerror</code> 捕获运行时错误。</li><li>常见错误类型： <ul><li><code>InternalError</code>：内部错误（如递归爆栈）</li><li><code>RangeError</code>：范围错误（如 <code>new Array(-1)</code>）</li><li><code>EvalError</code>：<code>eval()</code> 使用错误</li><li><code>ReferenceError</code>：引用未定义变量</li><li><code>SyntaxError</code>：语法错误</li><li><code>TypeError</code>：类型错误（如 <code>[1,2].split(&#39;.&#39;)</code>）</li><li><code>URIError</code>：URI 处理错误（如 <code>decodeURI(&#39;%2&#39;)</code>）</li><li><code>Error</code>：通用错误类型</li></ul></li></ul><h3 id="_5-2-promise-错误" tabindex="-1"><a class="header-anchor" href="#_5-2-promise-错误" aria-hidden="true">#</a> 5.2 Promise 错误</h3><ul><li>通过监听 <code>window.onunhandledrejection</code> 捕获未处理的 Promise 错误。</li></ul><h3 id="_5-3-资源加载错误" tabindex="-1"><a class="header-anchor" href="#_5-3-资源加载错误" aria-hidden="true">#</a> 5.3 资源加载错误</h3><ul><li>通过监听 <code>window.addEventListener(&#39;error&#39;, ...)</code> 并判断 <code>event.target</code> 类型，捕获图片、脚本、样式等资源加载失败。</li></ul><h3 id="_5-4-框架错误处理" tabindex="-1"><a class="header-anchor" href="#_5-4-框架错误处理" aria-hidden="true">#</a> 5.4 框架错误处理</h3><ul><li>React：<code>componentDidCatch</code>、<code>ErrorBoundary</code></li><li>Vue：<code>errorCaptured</code> 钩子</li></ul><hr><h2 id="_6-其他补充" tabindex="-1"><a class="header-anchor" href="#_6-其他补充" aria-hidden="true">#</a> 6. 其他补充</h2><ul><li><strong>数据采集 SDK</strong><br> 推荐使用开源或自研 SDK，支持灵活配置、数据脱敏、批量上报等功能。</li><li><strong>数据上报优化</strong><ul><li>批量合并上报，减少请求次数</li><li>离线缓存，断网后重试</li></ul></li><li><strong>数据安全与隐私</strong><ul><li>遵守相关法律法规（如 GDPR）</li><li>对敏感数据进行脱敏处理</li></ul></li><li><strong>监控平台</strong><ul><li>可接入如 Sentry、Fundebug、阿里云前端监控等平台，快速搭建监控体系。</li></ul></li></ul><hr>',31),s=e("p",null,[e("strong",null,"参考资料")],-1),u={href:"https://developer.mozilla.org/zh-CN/docs/Web/API/Performance_API",target:"_blank",rel:"noopener noreferrer"},_={href:"https://developer.mozilla.org/zh-CN/docs/Web/API/Navigator/sendBeacon",target:"_blank",rel:"noopener noreferrer"},g={href:"https://juejin.cn/post/6844904069415641096",target:"_blank",rel:"noopener noreferrer"};function b(f,p){const r=a("ExternalLinkIcon");return n(),d("div",null,[h,e("blockquote",null,[s,e("ul",null,[e("li",null,[e("a",u,[i("MDN Web Docs - Performance API"),l(r)])]),e("li",null,[e("a",_,[i("MDN Web Docs - sendBeacon"),l(r)])]),e("li",null,[e("a",g,[i("前端监控最佳实践"),l(r)])])])])])}const m=o(t,[["render",b],["__file","Engineering8.html.vue"]]);export{m as default};
